insert into passages (id, text, difficulty_level, b, active) values
('63aec578-caaf-4d2f-8f9d-38d583b67671', 'Coffee is one of the most widely traded commodities in the world, grown in more than seventy countries across a narrow band near the equator often called the coffee belt. The plant requires specific conditions to thrive, including consistent rainfall, moderate temperatures, and well-drained soil, which is why production is concentrated in regions such as Latin America, sub-Saharan Africa, and Southeast Asia. Despite its popularity, coffee farming faces serious challenges. Climate change has begun to shift the temperature and rainfall patterns that coffee plants depend on, threatening yields in some of the world''s top producing regions. In response, researchers are developing more resilient coffee varieties and encouraging farmers to diversify their crops so they are not entirely dependent on a single, increasingly unpredictable harvest. Meanwhile, consumer demand for coffee continues to rise, particularly in countries where coffee culture is relatively new, adding further pressure on an already strained supply chain.', 3, 0.0, true),
('998733b2-7ca8-411f-8c5f-4c3f548e7b40', 'For much of human history, sleep was widely regarded simply as a period of inactivity, a biological necessity with little scientific interest beyond its basic function of rest. In recent decades, however, researchers have discovered that sleep plays a far more active and complex role than previously assumed. During sleep, the brain cycles through several distinct stages, each associated with different types of neural activity. One stage, known as rapid eye movement or REM sleep, is closely linked to dreaming and appears to play an important role in processing emotions and consolidating memories. Other stages, sometimes called deep sleep, are thought to be essential for physical recovery and for clearing waste products that accumulate in the brain during waking hours. Sleep researchers now argue that chronic sleep deprivation, rather than being a minor inconvenience, may contribute to a wide range of health problems, including impaired concentration, weakened immune function, and an increased risk of certain chronic diseases. As a result, public health campaigns in several countries have begun encouraging adults to treat adequate sleep as seriously as diet and exercise.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('653a0cea-64c8-43c2-87a8-b6b9727d3b6b', 'sentence_completion', 'She was ___ when she found out she had won the scholarship.', NULL, '[{"id": "d", "text": "thrilled"}, {"id": "b", "text": "indifferent"}, {"id": "c", "text": "unhappy"}, {"id": "a", "text": "tired"}]'::jsonb, 0, '{"strategy": "won the scholarship = זכתה במלגה. איך מרגישים אחרי זכייה?", "correct_reason": "thrilled = נרגשת מאוד. זכייה במלגה גורמת להתרגשות רבה.", "options_analysis": ["נכון! thrilled = נרגשת מאוד — תגובה טבעית לזכייה", "indifferent = אדישה — לא מתאים לתגובה לזכייה", "unhappy = לא מאושרת — סותר הישג חיובי", "tired = עייפה — לא קשור לתוצאה"]}', 0.92, 0.0, 0.25, 3, 'ai', NULL, true),
('4d455b74-b416-4c97-83ef-184f62964148', 'sentence_completion', 'The company announced that it would ___ hundreds of new employees this year.', NULL, '[{"id": "c", "text": "forget"}, {"id": "a", "text": "hire"}, {"id": "b", "text": "fire"}, {"id": "d", "text": "ignore"}]'::jsonb, 1, '{"strategy": "hundreds of new employees = מאות עובדים חדשים. מה עושה חברה עם עובדים חדשים?", "correct_reason": "hire = לגייס/להעסיק. חברה שמצהירה על עובדים חדשים מגייסת אותם.", "options_analysis": ["forget = לשכוח — לא רלוונטי", "נכון! hire = לגייס — מתאים ל''עובדים חדשים''", "fire = לפטר — הפוך מ''עובדים חדשים''", "ignore = להתעלם מ- — לא רלוונטי"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('99a889a9-eb67-4c66-b86e-fe1aee830714', 'sentence_completion', 'The teacher praised the student for his ___ effort throughout the semester.', NULL, '[{"id": "d", "text": "careless"}, {"id": "b", "text": "lazy"}, {"id": "c", "text": "consistent"}, {"id": "a", "text": "rude"}]'::jsonb, 2, '{"strategy": "praised for effort throughout the semester = שיבחה על מאמץ לאורך הסמסטר. איזה מאמץ ראוי לשבח?", "correct_reason": "consistent = עקבי. מאמץ עקבי לאורך זמן ראוי לשבח.", "options_analysis": ["careless = חסר זהירות — לא ראוי לשבח", "lazy = עצלן — הפוך ממאמץ ראוי לשבח", "נכון! consistent = עקבי — מאמץ יציב לאורך זמן", "rude = גס רוח — לא קשור למאמץ אקדמי"]}', 1.08, 0.0, 0.25, 3, 'ai', NULL, true),
('9b883487-775d-4806-a402-24b6a1a41049', 'sentence_completion', 'Because of the storm, the flight was ___ until further notice.', NULL, '[{"id": "c", "text": "celebrated"}, {"id": "a", "text": "confirmed"}, {"id": "b", "text": "enjoyed"}, {"id": "d", "text": "delayed"}]'::jsonb, 3, '{"strategy": "because of the storm = בגלל הסערה. מה קורה לטיסה בגלל סערה?", "correct_reason": "delayed = נדחתה/התעכבה. סערה גורמת לעיכוב טיסות.", "options_analysis": ["celebrated = נחגגה — לא רלוונטי", "confirmed = אושרה — לא הגיוני בגלל סערה", "enjoyed = נהנתה — לא רלוונטי לטיסה", "נכון! delayed = נדחתה — תוצאה טבעית של סערה"]}', 1.0, 0.0, 0.25, 3, 'ai', NULL, true),
('9ccd42d2-5d20-42d7-88c3-c550d90baf9e', 'sentence_completion', 'The doctor advised him to ___ smoking immediately for his health.', NULL, '[{"id": "c", "text": "quit"}, {"id": "d", "text": "increase"}, {"id": "a", "text": "start"}, {"id": "b", "text": "enjoy"}]'::jsonb, 0, '{"strategy": "for his health = למען בריאותו. מה ממליץ רופא לגבי עישון?", "correct_reason": "quit = להפסיק. רופא ממליץ להפסיק עישון מטעמי בריאות.", "options_analysis": ["נכון! quit = להפסיק — המלצה רפואית טבעית", "increase = להגביר — הפוך מהמלצה בריאותית", "start = להתחיל — הפוך מהמלצה בריאותית", "enjoy = ליהנות מ- — לא הגיוני להמלצת רופא"]}', 1.06, 0.0, 0.25, 3, 'ai', NULL, true),
('8b877f5c-fb65-40f2-b924-82cbeba06778', 'sentence_completion', 'The museum''s new exhibit ___ visitors from all over the country.', NULL, '[{"id": "b", "text": "ignored"}, {"id": "a", "text": "attracted"}, {"id": "d", "text": "repelled"}, {"id": "c", "text": "cancelled"}]'::jsonb, 1, '{"strategy": "new exhibit... visitors = תערוכה חדשה ומבקרים. מה עושה תערוכה מוצלחת למבקרים?", "correct_reason": "attracted = משכה. תערוכה מוצלחת מושכת מבקרים.", "options_analysis": ["ignored = התעלמה מ- — לא הגיוני לתערוכה", "נכון! attracted = משכה — תוצאה טבעית של תערוכה מוצלחת", "repelled = דחתה — הפוך ממשיכת מבקרים", "cancelled = ביטלה — לא רלוונטי למבקרים"]}', 1.46, 0.0, 0.25, 3, 'ai', NULL, true),
('a85572c3-849c-48f0-815f-26bc1108990b', 'sentence_completion', 'The negotiations were ___ after both sides refused to compromise.', NULL, '[{"id": "d", "text": "celebrated"}, {"id": "a", "text": "successful"}, {"id": "b", "text": "suspended"}, {"id": "c", "text": "expanded"}]'::jsonb, 2, '{"strategy": "refused to compromise = סירבו להתפשר. מה קורה למו''מ כשאין פשרה?", "correct_reason": "suspended = הושעו. סירוב להתפשר גורם להשעיית מו''מ.", "options_analysis": ["celebrated = נחגגו — לא רלוונטי למו''מ כושל", "successful = מוצלחות — סותר סירוב להתפשר", "נכון! suspended = הושעו — תוצאה טבעית מסירוב לפשרה", "expanded = הורחבו — לא הגיוני עם סירוב"]}', 1.59, 0.0, 0.25, 3, 'ai', NULL, true),
('41bbf68e-6d1f-4c97-bc74-4c01f8bcab43', 'sentence_completion', 'The volunteers worked ___ to clean up the beach before sunset.', NULL, '[{"id": "d", "text": "lazily"}, {"id": "b", "text": "rudely"}, {"id": "c", "text": "sadly"}, {"id": "a", "text": "quickly"}]'::jsonb, 3, '{"strategy": "before sunset = לפני השקיעה. מגבלת זמן דורשת איזו עבודה?", "correct_reason": "quickly = במהירות. מגבלת זמן מחייבת עבודה מהירה.", "options_analysis": ["lazily = בעצלתיים — סותר מגבלת זמן", "rudely = בגסות — לא קשור לקצב עבודה", "sadly = בעצב — לא קשור לקצב עבודה", "נכון! quickly = במהירות — מתאים למגבלת ''לפני השקיעה''"]}', 1.45, 0.0, 0.25, 3, 'ai', NULL, true),
('6e7fcfe7-ccbd-47b0-9a30-b27dd9b1eb08', 'sentence_completion', 'The article ___ several important facts that readers should know.', NULL, '[{"id": "b", "text": "highlights"}, {"id": "d", "text": "denies"}, {"id": "c", "text": "hides"}, {"id": "a", "text": "forgets"}]'::jsonb, 0, '{"strategy": "readers should know = הקוראים צריכים לדעת. מה עושה כתבה עם עובדות חשובות?", "correct_reason": "highlights = מדגישה. כתבה טובה מדגישה עובדות חשובות.", "options_analysis": ["נכון! highlights = מדגישה — מתאים למטרת הכתבה", "denies = מכחישה — לא הגיוני לכתבה עיתונאית", "hides = מסתירה — הפוך מהמטרה של ''readers should know''", "forgets = שוכחת — לא רלוונטי לכתבה כתובה"]}', 1.02, 0.0, 0.25, 3, 'ai', NULL, true),
('05ee05e2-89aa-4f0c-a5fa-9e2de31ea7ea', 'sentence_completion', 'Despite the difficult conditions, the team managed to ___ the project on time.', NULL, '[{"id": "c", "text": "postpone"}, {"id": "d", "text": "complete"}, {"id": "b", "text": "forget"}, {"id": "a", "text": "abandon"}]'::jsonb, 1, '{"strategy": "despite difficult conditions...managed to = למרות קשיים, הצליחו ל-. מה הצליחו לעשות בזמן?", "correct_reason": "complete = להשלים. הצוות הצליח להשלים את הפרויקט בזמן.", "options_analysis": ["postpone = לדחות — סותר ''on time''", "נכון! complete = להשלים — תואם ''managed to...on time''", "forget = לשכוח — לא הגיוני לפרויקט", "abandon = לנטוש — סותר ''managed to'' (הצלחה)"]}', 1.24, 0.0, 0.25, 3, 'ai', NULL, true),
('c37f407c-857a-41e8-a129-9e4ec9a9403f', 'sentence_completion', 'The witness''s testimony ___ the defendant''s version of events.', NULL, '[{"id": "b", "text": "ignored"}, {"id": "c", "text": "confused"}, {"id": "a", "text": "supported"}, {"id": "d", "text": "celebrated"}]'::jsonb, 2, '{"strategy": "testimony...version of events = עדות...גרסת האירועים. מה עושה עדות תואמת?", "correct_reason": "supported = תמכה ב-. עדות שתואמת גרסה תומכת בה.", "options_analysis": ["ignored = התעלמה מ- — לא רלוונטי לעדות בבית משפט", "confused = בלבלה — לא מתאר תמיכה בגרסה", "נכון! supported = תמכה — עדות שתואמת גרסה תומכת בה", "celebrated = חגגה — לא רלוונטי לעדות משפטית"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('95e624c7-68e7-4994-9ab4-086296b81ac5', 'sentence_completion', 'The new bridge will ___ travel time between the two cities significantly.', NULL, '[{"id": "d", "text": "celebrate"}, {"id": "a", "text": "ignore"}, {"id": "c", "text": "measure"}, {"id": "b", "text": "reduce"}]'::jsonb, 3, '{"strategy": "new bridge...travel time = גשר חדש...זמן נסיעה. מה עושה גשר חדש לזמן הנסיעה?", "correct_reason": "reduce = לקצר. גשר חדש בדרך כלל מקצר את זמן הנסיעה.", "options_analysis": ["celebrate = לחגוג — לא רלוונטי", "ignore = להתעלם מ- — לא הגיוני", "measure = למדוד — לא רלוונטי לגשר", "נכון! reduce = לקצר — גשר חדש בדרך כלל מקצר נסיעה"]}', 1.13, 0.0, 0.25, 3, 'ai', NULL, true),
('a909794b-2553-44e3-986b-1ee1aa796b87', 'restatement', 'The concert was cancelled because too few tickets were sold.', NULL, '[{"id": "b", "text": "Too few tickets being sold led to the concert''s cancellation."}, {"id": "a", "text": "The concert was cancelled although many tickets were sold."}, {"id": "d", "text": "The concert took place because many tickets were sold."}, {"id": "c", "text": "Many tickets were sold after the concert was cancelled."}]'::jsonb, 0, '{"strategy": "cancelled because...= בוטל בגלל. סיבה-תוצאה.", "correct_reason": "''too few tickets sold led to cancellation'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק כמו במקור", "סותר ''because'' — במקור זו הייתה הסיבה, לא ניגוד", "הפוך — ''many tickets sold'' סותר ''too few''", "הופך את סדר הזמן והסיבתיות"]}', 1.34, 0.0, 0.25, 3, 'ai', NULL, true),
('2fe52a9e-94fc-49a2-aa4d-b8b2854cddb2', 'restatement', 'He is not only a talented musician but also a skilled painter.', NULL, '[{"id": "a", "text": "He is a better musician than painter."}, {"id": "d", "text": "He is a talented musician as well as a skilled painter."}, {"id": "c", "text": "He is neither a musician nor a painter."}, {"id": "b", "text": "He used to be a musician but is now only a painter."}]'::jsonb, 1, '{"strategy": "not only...but also = לא רק... אלא גם. שתי תכונות במקביל.", "correct_reason": "''talented musician as well as skilled painter'' = אותן שתי תכונות בדיוק.", "options_analysis": ["לא נאמר במקור השוואה כזו בין התחומים", "נכון! אותן שתי תכונות בדיוק, בניסוח שונה", "סותר את שתי התכונות שהוזכרו במקור", "לא נאמר במקור שינוי כזה בזמן"]}', 0.94, 0.0, 0.25, 3, 'ai', NULL, true),
('afaf2f13-8ee9-43a0-b66f-2bc0f651667b', 'restatement', 'The company will not launch the product until testing is complete.', NULL, '[{"id": "d", "text": "The company launched the product without any testing."}, {"id": "a", "text": "The product was launched before testing was complete."}, {"id": "c", "text": "Testing must be complete before the product is launched."}, {"id": "b", "text": "Testing began after the product was launched."}]'::jsonb, 2, '{"strategy": "will not launch until = לא תשיק עד ש-. תנאי הכרחי.", "correct_reason": "''testing must be complete before launch'' = אותו תנאי הכרחי בדיוק.", "options_analysis": ["סותר את התנאי לגמרי", "הפוך — סותר את התנאי ''until testing is complete''", "נכון! אותו תנאי בדיוק: בדיקה חייבת להסתיים לפני השקה", "הופך את סדר האירועים"]}', 0.93, 0.0, 0.25, 3, 'ai', NULL, true),
('a1acb7e9-2853-45b9-b432-61f4b9bd140c', 'restatement', 'Even the most experienced climbers found the mountain extremely challenging.', NULL, '[{"id": "a", "text": "No climbers found the mountain challenging."}, {"id": "d", "text": "Only inexperienced climbers found the mountain challenging."}, {"id": "c", "text": "The mountain was easy even for beginners."}, {"id": "b", "text": "The mountain was so difficult that experienced climbers also struggled."}]'::jsonb, 3, '{"strategy": "even the most experienced...found challenging = אפילו המנוסים ביותר התקשו.", "correct_reason": "''so difficult that experienced climbers also struggled'' = אותה משמעות: קושי קיצוני שהשפיע גם על מומחים.", "options_analysis": ["סותר את המקור — היו כאלה שהתקשו", "הפוך — במקור דווקא המנוסים כן התקשו", "סותר לגמרי את ''extremely challenging''", "נכון! אותה משמעות: קושי קיצוני שהשפיע גם על המנוסים"]}', 0.95, 0.0, 0.25, 3, 'ai', NULL, true),
('dbff49bc-2aea-4581-8f1b-ea67201f6c10', 'restatement', 'The government introduced new taxes in order to reduce the national debt.', NULL, '[{"id": "d", "text": "New taxes were introduced with the goal of lowering the national debt."}, {"id": "b", "text": "The government reduced taxes to increase the national debt."}, {"id": "a", "text": "The national debt caused the government to remove taxes."}, {"id": "c", "text": "The government introduced taxes without any specific goal."}]'::jsonb, 0, '{"strategy": "in order to reduce = כדי להפחית. מטרה ברורה למס החדש.", "correct_reason": "''introduced with the goal of lowering debt'' = אותה מטרה בדיוק.", "options_analysis": ["נכון! אותה מטרה בדיוק: מיסים חדשים כדי להפחית חוב", "הפוך — ''reduced taxes'' סותר ''new taxes''", "הופך סיבה ותוצאה", "סותר ''in order to'' — הייתה מטרה ברורה"]}', 1.37, 0.0, 0.25, 3, 'ai', NULL, true),
('e88e6af0-073a-4762-9b31-d37d13b2b4c4', 'restatement', 'Unlike her brother, she has always been interested in science.', NULL, '[{"id": "d", "text": "Her brother has always shared her interest in science."}, {"id": "b", "text": "Her interest in science differs from her brother''s lack of interest."}, {"id": "c", "text": "Her brother has always been interested in science, unlike her."}, {"id": "a", "text": "She has never been interested in science, unlike her brother."}]'::jsonb, 1, '{"strategy": "unlike her brother = בניגוד לאחיה. יש הבדל ברור ביניהם בנושא המדע.", "correct_reason": "''her interest differs from her brother''s lack of interest'' = משמר את הניגוד המדויק.", "options_analysis": ["סותר ''unlike'' — במקור יש הבדל ביניהם", "נכון! משמר את הניגוד בדיוק: היא מתעניינת, הוא לא", "הופך את התפקידים — במקור היא מתעניינת, לא הוא", "סותר לגמרי — היא כן מתעניינת"]}', 1.54, 0.0, 0.25, 3, 'ai', NULL, true),
('f599fd32-7790-4731-92d9-ee5512e19e1c', 'restatement', 'The bakery is known for its bread as much as for its pastries.', NULL, '[{"id": "c", "text": "The bakery stopped selling pastries because of its bread."}, {"id": "a", "text": "The bakery is known only for its pastries."}, {"id": "d", "text": "The bakery is equally known for its bread and its pastries."}, {"id": "b", "text": "The bakery is known for its bread but not its pastries."}]'::jsonb, 2, '{"strategy": "as much as = באותה מידה. מוניטין שווה בשני התחומים.", "correct_reason": "''equally known for bread and pastries'' = אותה משמעות בדיוק של שוויון.", "options_analysis": ["לא נאמר במקור כלל", "סותר ''as much as'' — יש מוניטין גם ללחם", "נכון! אותה משמעות בדיוק: מוניטין שווה בשניהם", "סותר את ''as much as'' שמציין שוויון"]}', 1.52, 0.0, 0.25, 3, 'ai', NULL, true),
('cda49214-fad2-462d-b05d-c864d9795a4c', 'restatement', 'The workshop, which lasted three hours, covered many useful topics.', NULL, '[{"id": "c", "text": "The workshop covered no useful topics despite lasting three hours."}, {"id": "d", "text": "The workshop was cancelled after three hours."}, {"id": "b", "text": "The workshop lasted only a few minutes."}, {"id": "a", "text": "The workshop lasted three hours and included many useful topics."}]'::jsonb, 3, '{"strategy": "which lasted three hours = שנמשך שלוש שעות. פרטים נלווים על הסדנה.", "correct_reason": "''lasted three hours and included many useful topics'' = אותם שני פרטים בדיוק.", "options_analysis": ["סותר ''covered many useful topics''", "לא נאמר במקור שהסדנה בוטלה", "סותר את ''three hours'' במפורש", "נכון! אותם שני פרטים בדיוק: משך ותוכן"]}', 1.53, 0.0, 0.25, 3, 'ai', NULL, true),
('324fc948-27ca-4517-ba10-711b7fe0ac88', 'restatement', 'The manager praised the team for solving the problem creatively.', NULL, '[{"id": "b", "text": "The manager complimented the team on their creative solution to the problem."}, {"id": "a", "text": "The team was criticized for their unoriginal solution."}, {"id": "d", "text": "The team ignored the problem completely."}, {"id": "c", "text": "The manager complained that the team failed to solve the problem."}]'::jsonb, 0, '{"strategy": "praised...for solving creatively = שיבח על פתרון יצירתי.", "correct_reason": "''complimented on their creative solution'' = אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: שבח על פתרון יצירתי", "סותר ''praised'' — הפוך לביקורת", "סותר לגמרי — הם כן טיפלו בבעיה", "סותר ''solving the problem'' — הם כן פתרו"]}', 1.0, 0.0, 0.25, 3, 'ai', NULL, true),
('1d9c69b7-8ef1-482a-8a3f-6012e9514840', 'restatement', 'The city has invested heavily in public transportation over the past decade.', NULL, '[{"id": "d", "text": "The city has spent very little on public transportation recently."}, {"id": "b", "text": "Over the past decade, the city has spent a great deal on public transportation."}, {"id": "c", "text": "The city plans to invest in public transportation next decade."}, {"id": "a", "text": "Public transportation in the city has been ignored for a decade."}]'::jsonb, 1, '{"strategy": "invested heavily = השקיעה רבות. השקעה משמעותית לאורך תקופה.", "correct_reason": "''spent a great deal over the past decade'' = אותה משמעות בדיוק.", "options_analysis": ["הפוך — ''very little'' סותר ''heavily''", "נכון! אותה משמעות בדיוק: השקעה רבה בעשור האחרון", "סותר את ציר הזמן — ''over the past decade'' הוא עבר, לא עתיד", "סותר ''invested heavily''"]}', 1.59, 0.0, 0.25, 3, 'ai', NULL, true),
('24a2a08e-e4d0-411a-b15a-4713912cde20', 'restatement', 'Although the movie received poor reviews, it became a box office success.', NULL, '[{"id": "a", "text": "The movie failed at the box office because of poor reviews."}, {"id": "d", "text": "The movie received excellent reviews and was also successful."}, {"id": "c", "text": "The movie was successful at the box office despite receiving poor reviews."}, {"id": "b", "text": "The movie was never released despite good reviews."}]'::jsonb, 2, '{"strategy": "although poor reviews...success = למרות ביקורות גרועות, הצליח בקופות.", "correct_reason": "''successful despite poor reviews'' = אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''success'' — הסרט כן הצליח", "סותר ''poor reviews'' — הביקורות היו גרועות", "נכון! אותה משמעות בדיוק: הצליח למרות ביקורות גרועות", "סותר לגמרי — הסרט כן יצא לאקרנים והצליח"]}', 1.05, 0.0, 0.25, 3, 'ai', NULL, true),
('7f36ccfc-8d62-451c-ad51-89790eda8605', 'restatement', 'The factory reduced its waste by recycling most of its materials.', NULL, '[{"id": "d", "text": "The factory stopped recycling to reduce waste."}, {"id": "c", "text": "The factory increased its waste by recycling materials."}, {"id": "a", "text": "The factory''s waste had no connection to recycling."}, {"id": "b", "text": "Recycling most of its materials allowed the factory to reduce waste."}]'::jsonb, 3, '{"strategy": "reduced waste by recycling = הפחיתה פסולת ע''י מחזור. סיבה-תוצאה.", "correct_reason": "''recycling allowed the factory to reduce waste'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר לגמרי — המפעל כן מיחזר", "הפוך — ''increased'' סותר ''reduced''", "סותר את הקשר הסיבתי המפורש במקור", "נכון! אותה סיבה-תוצאה בדיוק: מחזור הביא להפחתת פסולת"]}', 1.08, 0.0, 0.25, 3, 'ai', NULL, true),
('a67167df-ea2d-4c4a-a285-3a94ac596e0a', 'reading_comprehension', 'What is the passage mainly about?', '63aec578-caaf-4d2f-8f9d-38d583b67671', '[{"id": "d", "text": "The challenges facing global coffee production"}, {"id": "c", "text": "The history of coffee drinking around the world"}, {"id": "b", "text": "How to brew the perfect cup of coffee"}, {"id": "a", "text": "Why coffee is more popular than tea"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את גידול הקפה בעולם ואת האתגרים שהוא מתמודד איתם.", "correct_reason": "רוב הפסקה עוסקת בתנאי הגידול ובאיומי שינויי האקלים על תעשיית הקפה.", "options_analysis": ["נכון! גידול הקפה והאתגרים שהוא מתמודד איתם = הנושא הכולל", "לא הנושא, לא מוזכר כסקירה היסטורית", "לא מוזכר בפסקה כלל", "לא מוזכר בפסקה כלל"]}', 1.4, 0.0, 0.25, 3, 'ai', NULL, true),
('1002661d-3ca6-43d5-a657-161cc3b45a9d', 'reading_comprehension', 'According to the passage, where is coffee production concentrated?', '63aec578-caaf-4d2f-8f9d-38d583b67671', '[{"id": "d", "text": "Mainly in cold northern countries"}, {"id": "b", "text": "Regions such as Latin America, sub-Saharan Africa, and Southeast Asia"}, {"id": "a", "text": "Only in countries near the ocean"}, {"id": "c", "text": "Only in Latin America"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את האזורים המוזכרים בפסקה.", "correct_reason": "הפסקה אומרת: ''production is concentrated in regions such as Latin America, sub-Saharan Africa, and Southeast Asia''.", "options_analysis": ["סותר לגמרי — קפה גדל בקרבת קו המשווה, לא באזורים קרים", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "חלקי בלבד — הפסקה מזכירה עוד אזורים"]}', 1.38, 0.0, 0.25, 3, 'ai', NULL, true),
('011ff4af-f965-4d62-89a0-77cdbd181d81', 'reading_comprehension', 'The word "resilient" in the passage most closely means:', '63aec578-caaf-4d2f-8f9d-38d583b67671', '[{"id": "b", "text": "less flavorful than regular coffee"}, {"id": "d", "text": "artificially grown indoors"}, {"id": "a", "text": "able to withstand difficult conditions"}, {"id": "c", "text": "extremely rare and expensive"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''developing more resilient coffee varieties'' כדי להתמודד עם שינויי אקלים.", "correct_reason": "resilient = עמיד/חסון, מסוגל לעמוד בתנאים קשים.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "נכון! resilient = עמיד בתנאים קשים", "לא קשור למשמעות המילה"]}', 1.42, 0.0, 0.25, 3, 'ai', NULL, true),
('000b8d9c-b13a-4b70-a2db-80151eeb3de0', 'reading_comprehension', 'Why are researchers developing new coffee varieties, according to the passage?', '63aec578-caaf-4d2f-8f9d-38d583b67671', '[{"id": "b", "text": "To make coffee taste sweeter"}, {"id": "a", "text": "To make coffee easier to transport"}, {"id": "d", "text": "To reduce the price of coffee for consumers"}, {"id": "c", "text": "To respond to shifting temperature and rainfall patterns caused by climate change"}]'::jsonb, 3, '{"strategy": "שאלת סיבה — חפש את המניע המוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''climate change has begun to shift...patterns...In response, researchers are developing more resilient coffee varieties''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! הסיבה המדויקת מהפסקה"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('f855c05d-fc27-42cc-9bdf-844e5ebba7e7', 'reading_comprehension', 'Why are farmers encouraged to diversify their crops, according to the passage?', '63aec578-caaf-4d2f-8f9d-38d583b67671', '[{"id": "a", "text": "So they are not entirely dependent on a single, unpredictable harvest"}, {"id": "d", "text": "So they can sell coffee at higher prices"}, {"id": "c", "text": "So they can attract more tourists"}, {"id": "b", "text": "So they can stop growing coffee altogether"}]'::jsonb, 0, '{"strategy": "שאלת סיבה — חפש את ההסבר בפסקה.", "correct_reason": "הפסקה אומרת: ''encouraging farmers to diversify their crops so they are not entirely dependent on a single, increasingly unpredictable harvest''.", "options_analysis": ["נכון! הסיבה המדויקת מהפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "סותר את הפסקה — לא נאמר שיפסיקו לגדל קפה"]}', 1.33, 0.0, 0.25, 3, 'ai', NULL, true),
('057ccf47-feb3-4041-873f-3c7896f4beec', 'reading_comprehension', 'What additional pressure on coffee supply does the passage mention?', '63aec578-caaf-4d2f-8f9d-38d583b67671', '[{"id": "a", "text": "A global ban on coffee imports"}, {"id": "c", "text": "Rising consumer demand, especially where coffee culture is new"}, {"id": "b", "text": "A drop in coffee prices worldwide"}, {"id": "d", "text": "A decrease in the number of coffee-drinking countries"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הלחץ הנוסף המוזכר בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''consumer demand for coffee continues to rise, particularly in countries where coffee culture is relatively new, adding further pressure''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "סותר את הפסקה — הביקוש דווקא עולה"]}', 0.94, 0.0, 0.25, 3, 'ai', NULL, true),
('993cadea-92ab-4471-a6ab-2863b90ad8fe', 'reading_comprehension', 'What is the passage mainly about?', '998733b2-7ca8-411f-8c5f-4c3f548e7b40', '[{"id": "c", "text": "A comparison between REM sleep and deep sleep only"}, {"id": "b", "text": "How to fall asleep more quickly"}, {"id": "a", "text": "The growing scientific understanding of sleep''s active role in health"}, {"id": "d", "text": "Why ancient civilizations viewed sleep differently"}]'::jsonb, 2, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת כיצד ההבנה המדעית של השינה השתנתה והתעמקה.", "correct_reason": "כל הפסקה עוסקת במעבר מתפיסת שינה כפאסיבית לתפיסה מדעית מורכבת יותר עם השלכות בריאותיות.", "options_analysis": ["פרט משני בלבד, לא הנושא הכולל", "לא מוזכר בפסקה כלל", "נכון! ההבנה המדעית המתפתחת של תפקיד השינה הפעיל ובריאות = הנושא הכולל", "לא מוזכר בפסקה כלל"]}', 1.36, 0.0, 0.25, 3, 'ai', NULL, true),
('49784707-60a0-4422-a276-2a4e73095d3b', 'reading_comprehension', 'According to the passage, what was sleep widely regarded as for much of human history?', '998733b2-7ca8-411f-8c5f-4c3f548e7b40', '[{"id": "a", "text": "A skill that could be improved through training"}, {"id": "b", "text": "A complex biological process studied extensively"}, {"id": "c", "text": "A dangerous state to be avoided"}, {"id": "d", "text": "A period of inactivity with little scientific interest"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את התיאור ההיסטורי בתחילת הפסקה.", "correct_reason": "הפסקה אומרת: ''sleep was widely regarded simply as a period of inactivity...with little scientific interest''.", "options_analysis": ["לא נאמר בפסקה", "סותר את הפסקה — זה השתנה רק בעשורים האחרונים", "לא נאמר בפסקה", "נכון! נאמר במפורש בתחילת הפסקה"]}', 1.09, 0.0, 0.25, 3, 'ai', NULL, true),
('b3337cde-7252-4d62-81dc-63544e712b8b', 'reading_comprehension', 'The word "consolidating" in the passage most closely means:', '998733b2-7ca8-411f-8c5f-4c3f548e7b40', '[{"id": "d", "text": "strengthening and stabilizing"}, {"id": "c", "text": "randomly generating"}, {"id": "a", "text": "slowing down"}, {"id": "b", "text": "erasing completely"}]'::jsonb, 0, '{"strategy": "אוצר מילים בהקשר — ''consolidating memories'' מתייחס לתהליך חיזוק זיכרונות.", "correct_reason": "consolidating = מגבש/מחזק, הופך יציב יותר.", "options_analysis": ["נכון! consolidating = מחזק ומייצב", "לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה"]}', 1.17, 0.0, 0.25, 3, 'ai', NULL, true),
('de795c91-d204-4b6f-8285-2d034137805f', 'reading_comprehension', 'According to the passage, what is deep sleep thought to be essential for?', '998733b2-7ca8-411f-8c5f-4c3f548e7b40', '[{"id": "a", "text": "Increasing REM sleep duration"}, {"id": "c", "text": "Physical recovery and clearing waste products from the brain"}, {"id": "b", "text": "Preventing all dreaming"}, {"id": "d", "text": "Dreaming and emotional processing only"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התפקיד של השינה העמוקה בפסקה.", "correct_reason": "הפסקה אומרת: ''deep sleep, are thought to be essential for physical recovery and for clearing waste products''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "זה מתאר REM, לא שינה עמוקה"]}', 1.2, 0.0, 0.25, 3, 'ai', NULL, true),
('ebc9439e-6c15-49c0-9d3a-806759fe6085', 'reading_comprehension', 'What health risks does the passage associate with chronic sleep deprivation?', '998733b2-7ca8-411f-8c5f-4c3f548e7b40', '[{"id": "d", "text": "Only minor, temporary inconveniences"}, {"id": "a", "text": "Better memory consolidation"}, {"id": "b", "text": "Impaired concentration, weakened immune function, and increased disease risk"}, {"id": "c", "text": "Improved concentration and stronger immunity"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את רשימת הסיכונים בפסקה.", "correct_reason": "הפסקה אומרת: ''may contribute to...impaired concentration, weakened immune function, and an increased risk of certain chronic diseases''.", "options_analysis": ["סותר את הפסקה — מתואר כרציני, לא מינורי", "הפוך — חוסר שינה פוגע בזיכרון, לא משפר", "נכון! נאמר במפורש בפסקה", "הפוך גמור למה שנאמר בפסקה"]}', 1.1, 0.0, 0.25, 3, 'ai', NULL, true),
('69b360e5-403a-4e74-875d-ffa9753146c7', 'reading_comprehension', 'Why have public health campaigns begun encouraging adequate sleep, according to the passage?', '998733b2-7ca8-411f-8c5f-4c3f548e7b40', '[{"id": "d", "text": "Because sleep has no connection to physical health"}, {"id": "b", "text": "Because REM sleep has been proven harmful"}, {"id": "c", "text": "Because governments want to reduce coffee consumption"}, {"id": "a", "text": "Because sleep researchers now view chronic sleep deprivation as a serious health risk"}]'::jsonb, 3, '{"strategy": "שאלת סיבה — חפש את הקשר בין המחקר לקמפיינים בסוף הפסקה.", "correct_reason": "הפסקה מקשרת בין הבנת החוקרים לגבי סיכוני חוסר שינה לבין קמפיינים ציבוריים שמעודדים שינה מספקת.", "options_analysis": ["סותר את כל הפסקה", "סותר את הפסקה — REM דווקא מתואר כמועיל", "לא נאמר בפסקה כלל", "נכון! הקשר הסיבתי המדויק מהפסקה"]}', 0.95, 0.0, 0.25, 3, 'ai', NULL, true);